from collections import Counter
class Solution:
    def unequalTriplets(self, nums: List[int]) -> int:
        n = len(nums)
        ans, left = 0, 0
        for c in Counter(nums).values():
            ans += left * c * (n - left - c)
            left += c
        return ans

