class Solution {
public:
    int unequalTriplets(vector<int>& nums) {
        unordered_map<int,int> c;
        for (int x : nums) c[x]++;
        int n = nums.size(), ans = 0, left = 0;
        for (auto& [v, k] : c) {
            ans += left * k * (n - left - k);
            left += k;
        }
        return ans;
    }
};

