class Solution {
    public int unequalTriplets(int[] nums) {
        Map<Integer,Integer> c = new HashMap<>();
        for (int x : nums) c.merge(x, 1, Integer::sum);
        int n = nums.length, ans = 0, left = 0;
        for (int k : c.values()) {
            ans += left * k * (n - left - k);
            left += k;
        }
        return ans;
    }
}

